create table if not exists public.rack_item_allocations(id bigint generated by default as identity primary key,location_id bigint not null,location_code text,location_name text not null,item_id bigint not null,item_code text,item_name text not null,size text,unit text,assigned_qty numeric not null default 0,minimum_qty numeric default 0,maximum_qty numeric,primary_location text default 'No',remarks text,created_at timestamptz default now(),unique(location_id,item_id));
create table if not exists public.rack_transfers(id bigint generated by default as identity primary key,transfer_date date not null,from_location_id bigint not null,from_location_name text,to_location_id bigint not null,to_location_name text,item_id bigint not null,item_code text,item_name text,size text,unit text,qty numeric not null,transferred_by text,remarks text,created_at timestamptz default now());
alter table public.rack_item_allocations enable row level security;alter table public.rack_transfers enable row level security;
drop policy if exists "Public all rack allocations" on public.rack_item_allocations;create policy "Public all rack allocations" on public.rack_item_allocations for all using(true) with check(true);
drop policy if exists "Public all rack transfers" on public.rack_transfers;create policy "Public all rack transfers" on public.rack_transfers for all using(true) with check(true);